#include <stdio.h>#include <stdlib.h> // Required for qsort // Comparison function for qsort to sort in descending orderint compare(const void *a, const void *b) {    // To sort in descending order, we return (b - a)    // To sort in ascending order, we would return (a - b)    return (*(int*)b - *(int*)a);} int main() {    int test;    scanf("%d", &test);     while (test--) {        int oven, sec;        scanf("%d %d", &oven, &sec);                int cake[oven];        for (int i = 0; i < oven; i++) {            scanf("%d", &cake[i]);        }         // Sort in descending order using qsort - O(N log N)        // Parameters: array, number of elements, size of each element, comparison function        qsort(cake, oven, sizeof(int), compare);         // Using long long for 'final' to prevent potential integer overflow        // if cake values, oven, or sec are large.        long long final = 0;                if (sec >= oven) {            for (int i = 0; i < oven; i++) {                final += (long long)cake[i] * (sec - i);            }        } else {            for (int i = 0; i < sec; i++) {                final += (long long)cake[i] * (sec - i);            }        }         // Use %lld to print a long long        printf("%lld\n", final);    }     return 0;}